-- MAT-FUNC-049/050: controlled request cloning and recurring service schedules.

create table public.service_request_clone_provenance(
 id uuid primary key default extensions.gen_random_uuid(), client_organization_id uuid not null references public.organizations(id) on delete restrict,
 source_request_id uuid not null references public.service_requests(id) on delete restrict, source_request_version_id uuid not null references public.service_request_versions(id) on delete restrict,
 cloned_request_id uuid not null unique references public.service_requests(id) on delete restrict, cloned_request_version_id uuid not null references public.service_request_versions(id) on delete restrict,
 source_catalog_snapshot_hash text not null check(source_catalog_snapshot_hash~'^[0-9a-f]{64}$'), revalidated_catalog_snapshot_hash text not null check(revalidated_catalog_snapshot_hash~'^[0-9a-f]{64}$'),
 source_questionnaire_snapshot_hash text not null check(source_questionnaire_snapshot_hash~'^[0-9a-f]{64}$'), revalidated_questionnaire_snapshot_hash text not null check(revalidated_questionnaire_snapshot_hash~'^[0-9a-f]{64}$'),
 created_by uuid not null references auth.users(id), created_at timestamptz not null default clock_timestamp()
);

create table public.recurring_service_plans(
 id uuid primary key default extensions.gen_random_uuid(), client_organization_id uuid not null references public.organizations(id) on delete restrict,
 template_request_id uuid not null references public.service_requests(id) on delete restrict, current_version integer not null default 1 check(current_version>0),
 status text not null default 'ACTIVE' check(status in('ACTIVE','PAUSED','ENDED')), created_by uuid not null references auth.users(id),
 created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default clock_timestamp(), row_version integer not null default 1 check(row_version>0), unique(id,client_organization_id)
);
create table public.recurring_service_plan_versions(
 id uuid primary key default extensions.gen_random_uuid(), plan_id uuid not null references public.recurring_service_plans(id) on delete restrict,
 version_number integer not null check(version_number>0), cadence text not null check(cadence in('MONTHLY','QUARTERLY','ANNUALLY')),
 starts_on date not null, ends_on date, status text not null check(status in('ACTIVE','PAUSED','ENDED')), reason text not null check(length(btrim(reason))between 3 and 500),
 created_by uuid not null references auth.users(id), created_at timestamptz not null default clock_timestamp(), unique(plan_id,version_number), check(ends_on is null or ends_on>=starts_on)
);
create table public.recurring_service_occurrences(
 id uuid primary key default extensions.gen_random_uuid(), plan_id uuid not null references public.recurring_service_plans(id) on delete restrict,
 plan_version_id uuid not null references public.recurring_service_plan_versions(id) on delete restrict, client_organization_id uuid not null references public.organizations(id) on delete restrict,
 scheduled_on date not null, generated_request_id uuid not null unique references public.service_requests(id) on delete restrict,
 generated_request_version_id uuid not null references public.service_request_versions(id) on delete restrict, created_at timestamptz not null default clock_timestamp(), unique(plan_id,scheduled_on)
);

create or replace function private.reject_rfq_extension_history_mutation()returns trigger language plpgsql security definer set search_path=pg_catalog as $$begin raise exception'IMMUTABLE_RFQ_EXTENSION_HISTORY'using errcode='55000';end$$;
revoke all on function private.reject_rfq_extension_history_mutation()from public,anon,authenticated,service_role;
create trigger service_request_clone_provenance_immutable before update or delete on public.service_request_clone_provenance for each row execute function private.reject_rfq_extension_history_mutation();
create trigger recurring_service_plan_versions_immutable before update or delete on public.recurring_service_plan_versions for each row execute function private.reject_rfq_extension_history_mutation();
create trigger recurring_service_occurrences_immutable before update or delete on public.recurring_service_occurrences for each row execute function private.reject_rfq_extension_history_mutation();

create or replace function private.clone_request_core(p_source_request_id uuid,p_scheduled_on date,p_actor uuid,p_reason text,p_provenance boolean)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare sr public.service_requests%rowtype;sv public.service_request_versions%rowtype;csv public.catalog_service_versions%rowtype;qv public.questionnaire_versions%rowtype;q public.questionnaires%rowtype;nr uuid:=extensions.gen_random_uuid();nv uuid:=extensions.gen_random_uuid();h text;begin
 select*into sr from public.service_requests where id=p_source_request_id;if not found or not private.can_manage_client_request(sr.client_organization_id,p_actor)then raise exception'REQUEST_SCOPE_DENIED'using errcode='42501';end if;
 select*into sv from public.service_request_versions where id=sr.current_version_id;
 select*into csv from public.catalog_service_versions where id=coalesce((select current_published_version_id from public.catalog_services where id=sr.service_id),(select current_draft_version_id from public.catalog_services where id=sr.service_id))and service_id=sr.service_id and status not in('RETIRED','ARCHIVED');if not found then raise exception'SERVICE_VERSION_NOT_USABLE'using errcode='55000';end if;
 select*into qv from public.questionnaire_versions where id=sr.questionnaire_version_id;if found then select*into q from public.questionnaires where id=qv.questionnaire_id;select*into qv from public.questionnaire_versions where id=coalesce(q.current_published_version_id,q.current_draft_version_id)and status not in('SUPERSEDED','ARCHIVED');if not found then raise exception'QUESTIONNAIRE_VERSION_NOT_USABLE'using errcode='55000';end if;end if;
 h:=private.canonical_request_hash(jsonb_build_object('request_id',nr,'version',1,'source_request_id',sr.id,'catalog_hash',csv.content_hash,'questionnaire_hash',coalesce(qv.snapshot_hash,repeat('0',64)),'scheduled_on',p_scheduled_on));
 insert into public.service_requests(id,client_organization_id,site_id,library_id,service_id,questionnaire_version_id,status,created_by)values(nr,sr.client_organization_id,sr.site_id,sr.library_id,sr.service_id,qv.id,'DRAFT',p_actor);
 insert into public.service_request_versions(id,request_id,client_organization_id,library_id,version_number,description,urgency,desired_date,budget_minor,currency_code,required_quote_data,required_fields_complete,catalog_snapshot_hash,questionnaire_snapshot_hash,change_reason,content_hash,created_by)
 values(nv,nr,sr.client_organization_id,sr.library_id,1,sv.description,sv.urgency,coalesce(p_scheduled_on,sv.desired_date),sv.budget_minor,sv.currency_code,sv.required_quote_data,sv.required_fields_complete,csv.content_hash,coalesce(qv.snapshot_hash,repeat('0',64)),p_reason,h,p_actor);
 update public.service_requests set current_version_id=nv where id=nr;
 if p_provenance then insert into public.service_request_clone_provenance(client_organization_id,source_request_id,source_request_version_id,cloned_request_id,cloned_request_version_id,source_catalog_snapshot_hash,revalidated_catalog_snapshot_hash,source_questionnaire_snapshot_hash,revalidated_questionnaire_snapshot_hash,created_by)values(sr.client_organization_id,sr.id,sv.id,nr,nv,sv.catalog_snapshot_hash,csv.content_hash,sv.questionnaire_snapshot_hash,coalesce(qv.snapshot_hash,repeat('0',64)),p_actor);end if;
 return jsonb_build_object('request_id',nr,'request_version_id',nv,'status','DRAFT','catalog_snapshot_hash',csv.content_hash,'questionnaire_snapshot_hash',coalesce(qv.snapshot_hash,repeat('0',64)));
end$$;
revoke all on function private.clone_request_core(uuid,date,uuid,text,boolean)from public,anon,authenticated,service_role;

create or replace function public.clone_service_request(p_source_request_id uuid,p_desired_date date,p_change_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();sr public.service_requests%rowtype;h text;e public.idempotency_keys%rowtype;r jsonb;begin
 select*into sr from public.service_requests where id=p_source_request_id;if not found or not private.can_manage_client_request(sr.client_organization_id,a)then raise exception'REQUEST_SCOPE_DENIED'using errcode='42501';end if;if length(btrim(coalesce(p_change_reason,'')))not between 3 and 500 or length(coalesce(p_idempotency_key,''))not between 8 and 200 then raise exception'INVALID_CLONE_COMMAND'using errcode='22023';end if;
 h:=private.canonical_request_hash(jsonb_build_object('operation','rfq.request.clone.v1','source',p_source_request_id,'desired_date',p_desired_date,'reason',btrim(p_change_reason)));perform pg_advisory_xact_lock(hashtextextended(sr.client_organization_id::text||':rfq.request.clone:'||p_idempotency_key,0));select*into e from public.idempotency_keys where organization_id=sr.client_organization_id and operation_scope='rfq.request.clone'and key=p_idempotency_key;if found then if e.request_hash<>h then raise exception'IDEMPOTENCY_PAYLOAD_MISMATCH'using errcode='22000';end if;if e.status='COMPLETED'then return e.response_body;end if;raise exception'IDEMPOTENCY_IN_PROGRESS'using errcode='55000';end if;
 insert into public.idempotency_keys(organization_id,operation_scope,key,request_hash,created_by,expires_at)values(sr.client_organization_id,'rfq.request.clone',p_idempotency_key,h,a,clock_timestamp()+interval'30 days');r:=private.clone_request_core(p_source_request_id,p_desired_date,a,btrim(p_change_reason),true);r:=r||jsonb_build_object('outcome','SERVICE_REQUEST_CLONED','source_request_id',p_source_request_id);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(sr.client_organization_id,a,'USER','rfq.request.cloned','service_request',r->>'request_id',p_correlation_id,jsonb_build_object('source_request_id',p_source_request_id,'revalidated',true),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(sr.client_organization_id,'service_request',r->>'request_id','ServiceRequestClonedV1',p_correlation_id,r,p_idempotency_key);update public.idempotency_keys set status='COMPLETED',response_code=201,response_body=r,completed_at=clock_timestamp()where organization_id=sr.client_organization_id and operation_scope='rfq.request.clone'and key=p_idempotency_key;return r;end$$;

create or replace function public.create_recurring_service_plan(p_template_request_id uuid,p_cadence text,p_starts_on date,p_ends_on date,p_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();sr public.service_requests%rowtype;cv public.catalog_service_versions%rowtype;h text;e public.idempotency_keys%rowtype;pid uuid:=extensions.gen_random_uuid();vid uuid:=extensions.gen_random_uuid();r jsonb;begin
 select*into sr from public.service_requests where id=p_template_request_id;if not found or not private.can_manage_client_request(sr.client_organization_id,a)then raise exception'REQUEST_SCOPE_DENIED'using errcode='42501';end if;select*into cv from public.catalog_service_versions where id=coalesce((select current_published_version_id from public.catalog_services where id=sr.service_id),(select current_draft_version_id from public.catalog_services where id=sr.service_id));if not found or not cv.recurring_eligible then raise exception'SERVICE_NOT_RECURRING_ELIGIBLE'using errcode='22023';end if;if p_cadence not in('MONTHLY','QUARTERLY','ANNUALLY')or p_starts_on is null or(p_ends_on is not null and p_ends_on<p_starts_on)or length(btrim(coalesce(p_reason,'')))not between 3 and 500 then raise exception'INVALID_RECURRING_PLAN'using errcode='22023';end if;
 h:=private.canonical_request_hash(jsonb_build_object('operation','recurring.plan.create.v1','template',p_template_request_id,'cadence',p_cadence,'starts_on',p_starts_on,'ends_on',p_ends_on,'reason',btrim(p_reason)));perform pg_advisory_xact_lock(hashtextextended(sr.client_organization_id::text||':recurring.plan.create:'||p_idempotency_key,0));select*into e from public.idempotency_keys where organization_id=sr.client_organization_id and operation_scope='recurring.plan.create'and key=p_idempotency_key;if found then if e.request_hash<>h then raise exception'IDEMPOTENCY_PAYLOAD_MISMATCH'using errcode='22000';end if;if e.status='COMPLETED'then return e.response_body;end if;raise exception'IDEMPOTENCY_IN_PROGRESS'using errcode='55000';end if;insert into public.idempotency_keys(organization_id,operation_scope,key,request_hash,created_by,expires_at)values(sr.client_organization_id,'recurring.plan.create',p_idempotency_key,h,a,clock_timestamp()+interval'30 days');insert into public.recurring_service_plans(id,client_organization_id,template_request_id,created_by)values(pid,sr.client_organization_id,p_template_request_id,a);insert into public.recurring_service_plan_versions(id,plan_id,version_number,cadence,starts_on,ends_on,status,reason,created_by)values(vid,pid,1,p_cadence,p_starts_on,p_ends_on,'ACTIVE',btrim(p_reason),a);r:=jsonb_build_object('outcome','RECURRING_PLAN_CREATED','plan_id',pid,'plan_version_id',vid,'status','ACTIVE');insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(sr.client_organization_id,a,'USER','recurring.plan.created','recurring_service_plan',pid::text,p_correlation_id,jsonb_build_object('cadence',p_cadence,'template_request_id',p_template_request_id),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(sr.client_organization_id,'recurring_service_plan',pid::text,'RecurringServicePlanCreatedV1',p_correlation_id,r,p_idempotency_key);update public.idempotency_keys set status='COMPLETED',response_code=201,response_body=r,completed_at=clock_timestamp()where organization_id=sr.client_organization_id and operation_scope='recurring.plan.create'and key=p_idempotency_key;return r;end$$;

create or replace function public.transition_recurring_service_plan(p_plan_id uuid,p_action text,p_reason text,p_expected_row_version integer,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();p public.recurring_service_plans%rowtype;v public.recurring_service_plan_versions%rowtype;ns text;h text;e public.idempotency_keys%rowtype;nvid uuid:=extensions.gen_random_uuid();r jsonb;begin select*into p from public.recurring_service_plans where id=p_plan_id;if not found or not private.can_manage_client_request(p.client_organization_id,a)then raise exception'RECURRING_PLAN_SCOPE_DENIED'using errcode='42501';end if;ns:=case p_action when'PAUSE'then'PAUSED'when'RESUME'then'ACTIVE'when'END'then'ENDED'else null end;if ns is null or(p.status='ENDED')or(p.status='ACTIVE'and p_action<>'PAUSE'and p_action<>'END')or(p.status='PAUSED'and p_action<>'RESUME'and p_action<>'END')then raise exception'INVALID_RECURRING_TRANSITION'using errcode='55000';end if;select*into v from public.recurring_service_plan_versions where plan_id=p.id and version_number=p.current_version;h:=private.canonical_request_hash(jsonb_build_object('operation','recurring.plan.transition.v1','plan',p.id,'action',p_action,'expected',p_expected_row_version,'reason',btrim(p_reason)));perform pg_advisory_xact_lock(hashtextextended('recurring-plan:'||p.id::text,0));select*into p from public.recurring_service_plans where id=p.id for update;if p.row_version<>p_expected_row_version then raise exception'STALE_RECURRING_PLAN_VERSION'using errcode='40001';end if;select*into e from public.idempotency_keys where organization_id=p.client_organization_id and operation_scope='recurring.plan.transition'and key=p_idempotency_key;if found then if e.request_hash<>h then raise exception'IDEMPOTENCY_PAYLOAD_MISMATCH'using errcode='22000';end if;if e.status='COMPLETED'then return e.response_body;end if;end if;if not found then insert into public.idempotency_keys(organization_id,operation_scope,key,request_hash,created_by,expires_at)values(p.client_organization_id,'recurring.plan.transition',p_idempotency_key,h,a,clock_timestamp()+interval'30 days');end if;insert into public.recurring_service_plan_versions(id,plan_id,version_number,cadence,starts_on,ends_on,status,reason,created_by)values(nvid,p.id,p.current_version+1,v.cadence,v.starts_on,case when ns='ENDED'then greatest(v.starts_on,least(coalesce(v.ends_on,current_date),current_date))else v.ends_on end,ns,btrim(p_reason),a);update public.recurring_service_plans set status=ns,current_version=current_version+1,row_version=row_version+1,updated_at=clock_timestamp()where id=p.id;r:=jsonb_build_object('outcome','RECURRING_PLAN_'||ns,'plan_id',p.id,'plan_version_id',nvid,'status',ns,'row_version',p.row_version+1);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p.client_organization_id,a,'USER','recurring.plan.'||lower(p_action),'recurring_service_plan',p.id::text,p_correlation_id,jsonb_build_object('from_status',p.status,'to_status',ns,'reason',btrim(p_reason)),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p.client_organization_id,'recurring_service_plan',p.id::text,'RecurringServicePlan'||initcap(lower(ns))||'V1',p_correlation_id,r,p_idempotency_key);update public.idempotency_keys set status='COMPLETED',response_code=200,response_body=r,completed_at=clock_timestamp()where organization_id=p.client_organization_id and operation_scope='recurring.plan.transition'and key=p_idempotency_key;return r;end$$;

create or replace function public.generate_recurring_service_requests(p_plan_id uuid,p_through_date date,p_max_occurrences integer,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();p public.recurring_service_plans%rowtype;v public.recurring_service_plan_versions%rowtype;h text;e public.idempotency_keys%rowtype;d date;i int:=0;x jsonb;r jsonb;months int;begin select*into p from public.recurring_service_plans where id=p_plan_id;if not found or not private.can_manage_client_request(p.client_organization_id,a)then raise exception'RECURRING_PLAN_SCOPE_DENIED'using errcode='42501';end if;if p.status<>'ACTIVE'then raise exception'RECURRING_PLAN_NOT_ACTIVE'using errcode='55000';end if;select*into v from public.recurring_service_plan_versions where plan_id=p.id and version_number=p.current_version;months:=case v.cadence when'MONTHLY'then 1 when'QUARTERLY'then 3 else 12 end;if p_max_occurrences not between 1 and 24 or p_through_date<current_date or p_through_date>current_date+366 then raise exception'RECURRING_GENERATION_BOUNDS_EXCEEDED'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('operation','recurring.generate.v1','plan',p.id,'plan_version',v.id,'through',p_through_date,'max',p_max_occurrences));perform pg_advisory_xact_lock(hashtextextended('recurring-plan:'||p.id::text,0));select*into e from public.idempotency_keys where organization_id=p.client_organization_id and operation_scope='recurring.generate'and key=p_idempotency_key;if found then if e.request_hash<>h then raise exception'IDEMPOTENCY_PAYLOAD_MISMATCH'using errcode='22000';end if;if e.status='COMPLETED'then return e.response_body;end if;end if;if not found then insert into public.idempotency_keys(organization_id,operation_scope,key,request_hash,created_by,expires_at)values(p.client_organization_id,'recurring.generate',p_idempotency_key,h,a,clock_timestamp()+interval'30 days');end if;d:=v.starts_on;while d<=p_through_date and(v.ends_on is null or d<=v.ends_on)and i<p_max_occurrences loop if not exists(select 1 from public.recurring_service_occurrences where plan_id=p.id and scheduled_on=d)then x:=private.clone_request_core(p.template_request_id,d,a,'Génération prestation récurrente',false);insert into public.recurring_service_occurrences(plan_id,plan_version_id,client_organization_id,scheduled_on,generated_request_id,generated_request_version_id)values(p.id,v.id,p.client_organization_id,d,(x->>'request_id')::uuid,(x->>'request_version_id')::uuid);i:=i+1;end if;d:=(d+make_interval(months=>months))::date;end loop;r:=jsonb_build_object('outcome','RECURRING_REQUESTS_GENERATED','plan_id',p.id,'generated_count',i,'through_date',p_through_date,'autonomous_invitations',false,'autonomous_spend',false);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p.client_organization_id,a,'USER','recurring.requests.generated','recurring_service_plan',p.id::text,p_correlation_id,jsonb_build_object('generated_count',i,'through_date',p_through_date),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p.client_organization_id,'recurring_service_plan',p.id::text,'RecurringServiceRequestsGeneratedV1',p_correlation_id,r,p_idempotency_key);update public.idempotency_keys set status='COMPLETED',response_code=201,response_body=r,completed_at=clock_timestamp()where organization_id=p.client_organization_id and operation_scope='recurring.generate'and key=p_idempotency_key;return r;end$$;

alter table public.service_request_clone_provenance enable row level security;alter table public.recurring_service_plans enable row level security;alter table public.recurring_service_plan_versions enable row level security;alter table public.recurring_service_occurrences enable row level security;
create policy clone_provenance_tenant_read on public.service_request_clone_provenance for select to authenticated using(private.can_manage_client_request(client_organization_id)or private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','READ_ONLY_AUDITOR']));
create policy recurring_plans_tenant_read on public.recurring_service_plans for select to authenticated using(private.can_manage_client_request(client_organization_id)or private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','READ_ONLY_AUDITOR']));
create policy recurring_plan_versions_tenant_read on public.recurring_service_plan_versions for select to authenticated using(exists(select 1 from public.recurring_service_plans p where p.id=plan_id and(private.can_manage_client_request(p.client_organization_id)or private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','READ_ONLY_AUDITOR']))));
create policy recurring_occurrences_tenant_read on public.recurring_service_occurrences for select to authenticated using(private.can_manage_client_request(client_organization_id)or private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','READ_ONLY_AUDITOR']));
revoke all on public.service_request_clone_provenance,public.recurring_service_plans,public.recurring_service_plan_versions,public.recurring_service_occurrences from anon,authenticated,service_role;grant select on public.service_request_clone_provenance,public.recurring_service_plans,public.recurring_service_plan_versions,public.recurring_service_occurrences to authenticated;
revoke all on function public.clone_service_request(uuid,date,text,text,uuid),public.create_recurring_service_plan(uuid,text,date,date,text,text,uuid),public.transition_recurring_service_plan(uuid,text,text,integer,text,uuid),public.generate_recurring_service_requests(uuid,date,integer,text,uuid)from public,anon,service_role;grant execute on function public.clone_service_request(uuid,date,text,text,uuid),public.create_recurring_service_plan(uuid,text,date,date,text,text,uuid),public.transition_recurring_service_plan(uuid,text,text,integer,text,uuid),public.generate_recurring_service_requests(uuid,date,integer,text,uuid)to authenticated;
create index clone_provenance_tenant_source_idx on public.service_request_clone_provenance(client_organization_id,source_request_id,created_at desc);create index recurring_plans_tenant_status_idx on public.recurring_service_plans(client_organization_id,status,updated_at desc);create index recurring_occurrences_plan_date_idx on public.recurring_service_occurrences(plan_id,scheduled_on);
